Node* merge(Node* a, Node* b) {
    if(!a) return b;
    if(!b) return a;
    Node* result;
    if(a->data <= b->data) {
        result = a;
        result->bottom = merge(a->bottom, b);
    } else {
        result = b;
        result->bottom = merge(a, b->bottom);
    }
    result->next = NULL;
    return result;
}

Node* flatten(Node* head) {
    if(!head || !head->next) return head;
    head->next = flatten(head->next);
    head = merge(head, head->next);
    return head;
}
